export const CODE_FILES: CodeFile[] = [{"file":"01_prepare_data.py","lang":"py","lines":25,"code":"\"\"\"Download GLUE SST-2 and create train / dev / test CSV splits.\n\nSST-2 has no public test labels, so the official validation split (872 sentences)\nis used as the held-out TEST set, and 2,000 sentences are carved out of the\ntraining data as a DEV set for model selection / early stopping.\n\"\"\"\nimport os\n\nfrom datasets import load_dataset\nfrom sklearn.model_selection import train_test_split\n\nfrom utils import DATA_DIR, SEED\n\nos.makedirs(DATA_DIR, exist_ok=True)\nds = load_dataset(\"nyu-mll/glue\", \"sst2\")\ntrain_full = ds[\"train\"].to_pandas()[[\"sentence\", \"label\"]]\ntest = ds[\"validation\"].to_pandas()[[\"sentence\", \"label\"]]\n\ntrain, dev = train_test_split(train_full, test_size=2000, random_state=SEED, stratify=train_full[\"label\"])\nfor name, df in ((\"train\", train), (\"dev\", dev), (\"test\", test)):\n    df = df.copy()\n    df[\"sentence\"] = df[\"sentence\"].str.strip()\n    df.to_csv(os.path.join(DATA_DIR, f\"{name}.csv\"), index=False)\n    print(f\"{name:5s}: {len(df):6d} rows, positive share = {df['label'].mean():.3f}, \"\n          f\"mean length = {df['sentence'].str.split().str.len().mean():.1f} words\")"},{"file":"02_classical_baselines.py","lang":"py","lines":39,"code":"\"\"\"Classical baselines: TF-IDF features + Naive Bayes / Logistic Regression / Linear SVM.\"\"\"\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.naive_bayes import MultinomialNB\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.svm import LinearSVC\n\nfrom utils import Timer, compute_metrics, load_split, save_result, set_seed\n\nset_seed()\ntrain, test = load_split(\"train\"), load_split(\"test\")\n\nmodels = {\n    \"tfidf_nb\": MultinomialNB(alpha=0.5),\n    \"tfidf_logreg\": LogisticRegression(C=4.0, max_iter=2000),\n    \"tfidf_svm\": LinearSVC(C=0.5),\n}\n\nfor name, clf in models.items():\n    pipe = Pipeline([\n        (\"tfidf\", TfidfVectorizer(ngram_range=(1, 2), min_df=2, sublinear_tf=True)),\n        (\"clf\", clf),\n    ])\n    with Timer() as t_train:\n        pipe.fit(train[\"sentence\"], train[\"label\"])\n    with Timer() as t_inf:\n        pred = pipe.predict(test[\"sentence\"])\n    n_features = len(pipe.named_steps[\"tfidf\"].vocabulary_)\n    result = {\n        \"model\": name,\n        \"family\": \"classical\",\n        \"train_size\": len(train),\n        \"train_time_s\": t_train.seconds,\n        \"latency_ms_per_sample\": 1000 * t_inf.seconds / len(test),\n        \"parameters\": int(n_features * (2 if name == \"tfidf_nb\" else 1)),\n        **compute_metrics(test[\"label\"], pred),\n        \"predictions\": pred.tolist(),\n    }\n    save_result(name, result)"},{"file":"03_bilstm.py","lang":"py","lines":102,"code":"\"\"\"Recurrent baseline: a bidirectional LSTM trained from scratch (no pre-training).\"\"\"\nimport re\nfrom collections import Counter\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom torch.nn.utils.rnn import pad_sequence\n\nfrom utils import Timer, compute_metrics, load_split, save_result, set_seed\n\nset_seed()\ntrain, dev, test = load_split(\"train\"), load_split(\"dev\"), load_split(\"test\")\nTOKEN_RE = re.compile(r\"[a-z0-9']+|[^\\sa-z0-9]\")\n\n\ndef tokenize(text):\n    return TOKEN_RE.findall(str(text).lower())\n\n\ncounter = Counter(tok for s in train[\"sentence\"] for tok in tokenize(s))\nvocab = {\"<pad>\": 0, \"<unk>\": 1}\nfor tok, c in counter.items():\n    if c >= 2:\n        vocab[tok] = len(vocab)\n\n\ndef encode(df):\n    X = [torch.tensor([vocab.get(t, 1) for t in tokenize(s)] or [1]) for s in df[\"sentence\"]]\n    return X, df[\"label\"].values\n\n\nclass BiLSTM(nn.Module):\n    def __init__(self, vocab_size, emb=128, hidden=128):\n        super().__init__()\n        self.emb = nn.Embedding(vocab_size, emb, padding_idx=0)\n        self.lstm = nn.LSTM(emb, hidden, batch_first=True, bidirectional=True)\n        self.drop = nn.Dropout(0.3)\n        self.out = nn.Linear(2 * hidden, 2)\n\n    def forward(self, x):\n        h, _ = self.lstm(self.emb(x))\n        mask = (x != 0).unsqueeze(-1)\n        h = h.masked_fill(~mask, -1e9).max(dim=1).values  # max-pooling over time\n        return self.out(self.drop(h))\n\n\ndef batches(X, y, bs, shuffle):\n    idx = np.random.permutation(len(X)) if shuffle else np.arange(len(X))\n    for i in range(0, len(X), bs):\n        b = idx[i:i + bs]\n        yield pad_sequence([X[j] for j in b], batch_first=True), torch.tensor(y[b])\n\n\ndef predict(model, X):\n    model.eval()\n    preds = []\n    with torch.no_grad():\n        for xb, _ in batches(X, np.zeros(len(X), dtype=int), 256, False):\n            preds.append(model(xb).argmax(-1))\n    return torch.cat(preds).numpy()\n\n\nXtr, ytr = encode(train)\nXdv, ydv = encode(dev)\nXte, yte = encode(test)\nmodel = BiLSTM(len(vocab))\nopt = torch.optim.Adam(model.parameters(), lr=1e-3)\nloss_fn = nn.CrossEntropyLoss()\nhistory, best_acc, best_state = [], 0.0, None\n\nwith Timer() as t_train:\n    for epoch in range(4):\n        model.train()\n        total = 0.0\n        for xb, yb in batches(Xtr, ytr, 64, True):\n            opt.zero_grad()\n            loss = loss_fn(model(xb), yb)\n            loss.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            opt.step()\n            total += loss.item() * len(yb)\n        dev_acc = float((predict(model, Xdv) == ydv).mean())\n        history.append({\"epoch\": epoch + 1, \"train_loss\": total / len(Xtr), \"dev_accuracy\": dev_acc})\n        print(history[-1], flush=True)\n        if dev_acc > best_acc:\n            best_acc, best_state = dev_acc, {k: v.clone() for k, v in model.state_dict().items()}\n\nmodel.load_state_dict(best_state)\nwith Timer() as t_inf:\n    pred = predict(model, Xte)\nsave_result(\"bilstm\", {\n    \"model\": \"bilstm\",\n    \"family\": \"recurrent\",\n    \"train_size\": len(train),\n    \"train_time_s\": t_train.seconds,\n    \"latency_ms_per_sample\": 1000 * t_inf.seconds / len(test),\n    \"parameters\": sum(p.numel() for p in model.parameters()),\n    \"history\": history,\n    **compute_metrics(yte, pred),\n    \"predictions\": pred.tolist(),\n})"},{"file":"04_finetune_transformer.py","lang":"py","lines":105,"code":"\"\"\"Fine-tune a pre-trained Transformer encoder for binary sentiment classification.\n\nUsage:\n    python 04_finetune_transformer.py --model prajjwal1/bert-small --train-size 8000 --epochs 2\n\"\"\"\nimport argparse\nimport math\n\nimport torch\nfrom torch.utils.data import DataLoader\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer, get_linear_schedule_with_warmup\n\nfrom utils import Timer, compute_metrics, load_split, save_result, set_seed\n\np = argparse.ArgumentParser()\np.add_argument(\"--model\", required=True)\np.add_argument(\"--train-size\", type=int, default=8000)\np.add_argument(\"--epochs\", type=int, default=2)\np.add_argument(\"--lr\", type=float, default=5e-5)\np.add_argument(\"--batch-size\", type=int, default=32)\np.add_argument(\"--max-len\", type=int, default=64)\np.add_argument(\"--tag\", default=None, help=\"name of the result file\")\np.add_argument(\"--save-dir\", default=None, help=\"optionally save the fine-tuned model here\")\nargs = p.parse_args()\n\nset_seed()\ntrain, dev, test = load_split(\"train\"), load_split(\"dev\"), load_split(\"test\")\nif args.train_size < len(train):\n    train = train.sample(n=args.train_size, random_state=42)\n\ntok = AutoTokenizer.from_pretrained(args.model)\nmodel = AutoModelForSequenceClassification.from_pretrained(args.model, num_labels=2)\n\n\ndef make_loader(df, shuffle):\n    pairs = list(zip(df[\"sentence\"].tolist(), df[\"label\"].tolist()))\n\n    def collate(batch):\n        enc = tok([b[0] for b in batch], truncation=True, max_length=args.max_len,\n                  padding=True, return_tensors=\"pt\")\n        enc[\"labels\"] = torch.tensor([b[1] for b in batch])\n        return enc\n\n    return DataLoader(pairs, batch_size=args.batch_size, shuffle=shuffle, collate_fn=collate)\n\n\ndef predict(loader):\n    model.eval()\n    preds = []\n    with torch.no_grad():\n        for batch in loader:\n            batch.pop(\"labels\")\n            preds.append(model(**batch).logits.argmax(-1))\n    return torch.cat(preds).numpy()\n\n\ntrain_dl, dev_dl, test_dl = make_loader(train, True), make_loader(dev, False), make_loader(test, False)\nsteps = args.epochs * len(train_dl)\nopt = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=0.01)\nsched = get_linear_schedule_with_warmup(opt, num_warmup_steps=math.ceil(0.1 * steps), num_training_steps=steps)\n\nhistory, best_acc, best_state = [], -1.0, None\nwith Timer() as t_train:\n    for epoch in range(args.epochs):\n        model.train()\n        total, n = 0.0, 0\n        for step, batch in enumerate(train_dl):\n            out = model(**batch)  # cross-entropy loss is computed inside the model\n            out.loss.backward()\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            opt.step()\n            sched.step()\n            opt.zero_grad()\n            total += out.loss.item() * len(batch[\"labels\"])\n            n += len(batch[\"labels\"])\n            if step % 50 == 0:\n                print(f\"epoch {epoch + 1} step {step}/{len(train_dl)} loss {total / n:.4f}\", flush=True)\n        dev_acc = float((predict(dev_dl) == dev[\"label\"].values).mean())\n        history.append({\"epoch\": epoch + 1, \"train_loss\": total / n, \"dev_accuracy\": dev_acc})\n        print(history[-1], flush=True)\n        if dev_acc > best_acc:\n            best_acc, best_state = dev_acc, {k: v.detach().clone() for k, v in model.state_dict().items()}\n\nmodel.load_state_dict(best_state)\nwith Timer() as t_inf:\n    pred = predict(test_dl)\n\nif args.save_dir:\n    model.save_pretrained(args.save_dir)\n    tok.save_pretrained(args.save_dir)\n\ntag = args.tag or f\"ft_{args.model.split('/')[-1]}_{args.train_size}\"\nsave_result(tag, {\n    \"model\": args.model,\n    \"family\": \"transformer-finetuned\",\n    \"train_size\": len(train),\n    \"epochs\": args.epochs,\n    \"lr\": args.lr,\n    \"train_time_s\": t_train.seconds,\n    \"latency_ms_per_sample\": 1000 * t_inf.seconds / len(test),\n    \"parameters\": sum(p.numel() for p in model.parameters()),\n    \"history\": history,\n    **compute_metrics(test[\"label\"].values, pred),\n    \"predictions\": pred.tolist(),\n})"},{"file":"05_pretrained_transformers.py","lang":"py","lines":60,"code":"\"\"\"Off-the-shelf Transformer models evaluated without any training on our side:\n\n1. distilbert-base-uncased-finetuned-sst-2-english  (in-domain: already fine-tuned on SST-2)\n2. cardiffnlp/twitter-roberta-base-sentiment-latest (out-of-domain: trained on tweets, 3 classes)\n3. cross-encoder/nli-distilroberta-base              (zero-shot classification through NLI)\n\"\"\"\nimport numpy as np\nfrom transformers import pipeline\n\nfrom utils import Timer, compute_metrics, load_split, save_result, set_seed\n\nset_seed()\ntest = load_split(\"test\")\ntexts, y = test[\"sentence\"].tolist(), test[\"label\"].values\n\n\ndef n_params(pipe):\n    return sum(p.numel() for p in pipe.model.parameters())\n\n\ndef save(tag, family, model_name, pred, seconds, params):\n    save_result(tag, {\n        \"model\": model_name,\n        \"family\": family,\n        \"train_size\": 0,\n        \"train_time_s\": 0.0,\n        \"latency_ms_per_sample\": 1000 * seconds / len(texts),\n        \"parameters\": params,\n        **compute_metrics(y, pred),\n        \"predictions\": pred.tolist(),\n    })\n\n\n# 1. In-domain fine-tuned DistilBERT\nname = \"distilbert-base-uncased-finetuned-sst-2-english\"\nclf = pipeline(\"sentiment-analysis\", model=name, device=-1)\nwith Timer() as t:\n    out = clf(texts, batch_size=32, truncation=True)\nsave(\"pt_distilbert_sst2\", \"transformer-pretrained\", name,\n     np.array([int(o[\"label\"] == \"POSITIVE\") for o in out]), t.seconds, n_params(clf))\n\n# 2. Out-of-domain Twitter RoBERTa: compare positive vs negative scores only (neutral ignored)\nname = \"cardiffnlp/twitter-roberta-base-sentiment-latest\"\nclf = pipeline(\"sentiment-analysis\", model=name, device=-1)\nwith Timer() as t:\n    out = clf(texts, batch_size=32, truncation=True, top_k=None)\npred = []\nfor scores in out:\n    s = {d[\"label\"].lower(): d[\"score\"] for d in scores}\n    pred.append(int(s[\"positive\"] >= s[\"negative\"]))\nsave(\"pt_twitter_roberta\", \"transformer-pretrained\", name, np.array(pred), t.seconds, n_params(clf))\n\n# 3. Zero-shot classification via natural language inference\nname = \"cross-encoder/nli-distilroberta-base\"\nzs = pipeline(\"zero-shot-classification\", model=name, device=-1)\nwith Timer() as t:\n    out = zs(texts, candidate_labels=[\"positive\", \"negative\"],\n             hypothesis_template=\"The sentiment of this movie review is {}.\", batch_size=32)\nsave(\"zs_nli_distilroberta\", \"transformer-zero-shot\", name,\n     np.array([int(o[\"labels\"][0] == \"positive\") for o in out]), t.seconds, n_params(zs))"},{"file":"06_learning_curve_classical.py","lang":"py","lines":22,"code":"\"\"\"Learning curve for the TF-IDF + Logistic Regression baseline (same sample sizes as the\nTransformer learning curve, so the data efficiency of pre-training can be compared).\"\"\"\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import Pipeline\n\nfrom utils import compute_metrics, load_split, save_result, set_seed\n\nSIZES = [500, 1000, 2000, 4000, 8000]\n\nset_seed()\ntrain, test = load_split(\"train\"), load_split(\"test\")\nfor n in SIZES:\n    sample = train.sample(n=n, random_state=42)  # identical sample to 04_finetune_transformer.py\n    pipe = Pipeline([\n        (\"tfidf\", TfidfVectorizer(ngram_range=(1, 2), min_df=1, sublinear_tf=True)),\n        (\"clf\", LogisticRegression(C=4.0, max_iter=2000)),\n    ])\n    pipe.fit(sample[\"sentence\"], sample[\"label\"])\n    pred = pipe.predict(test[\"sentence\"])\n    save_result(f\"lc_tfidf_logreg_{n}\", {\"model\": \"tfidf_logreg\", \"train_size\": n,\n                                          **compute_metrics(test[\"label\"], pred)})"},{"file":"07_attention_visualisation.py","lang":"py","lines":47,"code":"\"\"\"Visualise self-attention of a fine-tuned DistilBERT on example sentences\n(helps explain how the Transformer resolves negation and contrast).\"\"\"\nimport os\n\nimport matplotlib.pyplot as plt\nimport torch\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer\n\nfrom utils import FIG_DIR\n\nNAME = \"distilbert-base-uncased-finetuned-sst-2-english\"\ntok = AutoTokenizer.from_pretrained(NAME)\nmodel = AutoModelForSequenceClassification.from_pretrained(NAME, output_attentions=True).eval()\n\nsentence = \"the plot was not good , but the acting was brilliant\"\nenc = tok(sentence, return_tensors=\"pt\")\nwith torch.no_grad():\n    out = model(**enc)\ntokens = tok.convert_ids_to_tokens(enc[\"input_ids\"][0])\nprobs = out.logits.softmax(-1)[0].tolist()\nprint(f\"P(negative)={probs[0]:.3f}  P(positive)={probs[1]:.3f}\")\n\n# out.attentions: tuple(layers) of [batch, heads, seq, seq]; average heads in the last layer\natt = out.attentions[-1][0].mean(0).numpy()\nfig, ax = plt.subplots(figsize=(7, 6))\nim = ax.imshow(att, cmap=\"Blues\")\nax.set_xticks(range(len(tokens)), tokens, rotation=60, ha=\"right\")\nax.set_yticks(range(len(tokens)), tokens)\nax.set_xlabel(\"attended-to token (key)\")\nax.set_ylabel(\"query token\")\nax.set_title(\"DistilBERT, last layer, mean of 12 heads\")\nfig.colorbar(im, ax=ax, fraction=0.046)\nfig.tight_layout()\nos.makedirs(FIG_DIR, exist_ok=True)\nfig.savefig(os.path.join(FIG_DIR, \"attention_heatmap.png\"), dpi=200)\n\n# [CLS] attention row in every layer -> which words drive the sentence representation\nfig, ax = plt.subplots(figsize=(8, 3.2))\ncls = torch.stack([a[0].mean(0)[0] for a in out.attentions]).numpy()  # layers x seq\nim = ax.imshow(cls, cmap=\"Oranges\", aspect=\"auto\")\nax.set_xticks(range(len(tokens)), tokens, rotation=60, ha=\"right\")\nax.set_yticks(range(cls.shape[0]), [f\"L{i + 1}\" for i in range(cls.shape[0])])\nax.set_title(\"Attention from [CLS] to each token, per layer\")\nfig.colorbar(im, ax=ax, fraction=0.03)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"cls_attention_layers.png\"), dpi=200)\nprint(\"saved attention figures\")"},{"file":"08_report.py","lang":"py","lines":220,"code":"\"\"\"Aggregate all results into tables and figures used in the paper and the slides.\"\"\"\nimport glob\nimport json\nimport os\nimport re\n\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\n\nfrom utils import FIG_DIR, RESULTS_DIR, load_split\n\nos.makedirs(FIG_DIR, exist_ok=True)\nplt.rcParams.update({\"font.family\": \"serif\", \"font.serif\": [\"Times New Roman\", \"DejaVu Serif\"],\n                     \"font.size\": 10, \"axes.spines.top\": False, \"axes.spines.right\": False,\n                     \"axes.grid\": True, \"grid.color\": \"#e4e3df\", \"grid.linewidth\": 0.6,\n                     \"axes.axisbelow\": True})\n# Categorical slots 1-3 of the validated reference palette, one per model family\nFAMILY_COLOR = {\"classical\": \"#2a78d6\", \"recurrent\": \"#eb6834\", \"transformer\": \"#1baf7a\"}\nINK, MUTED = \"#0b0b0b\", \"#52514e\"\n\nLABELS = {\n    \"tfidf_nb\": \"TF-IDF + Naive Bayes\",\n    \"tfidf_logreg\": \"TF-IDF + Logistic Regr.\",\n    \"tfidf_svm\": \"TF-IDF + Linear SVM\",\n    \"bilstm\": \"BiLSTM (from scratch)\",\n    \"zs_nli_distilroberta\": \"Zero-shot NLI DistilRoBERTa\",\n    \"pt_twitter_roberta\": \"Twitter-RoBERTa (off-the-shelf)\",\n    \"pt_distilbert_sst2\": \"DistilBERT-SST2 (off-the-shelf)\",\n    \"ft_bert-tiny_8000\": \"BERT-tiny fine-tuned (8k)\",\n    \"ft_bert-small_8000\": \"BERT-small fine-tuned (8k)\",\n    \"ft_distilbert_8000\": \"DistilBERT fine-tuned (8k)\",\n}\n\n\ndef label_for(tag):\n    if tag in LABELS:\n        return LABELS[tag]\n    m = re.match(r\"ft_(.+)_(\\d+)$\", tag)\n    return f\"{m.group(1)} fine-tuned ({int(m.group(2)) // 1000}k)\" if m else tag\n\n\ndef family_key(fam):\n    return \"transformer\" if fam.startswith(\"transformer\") else fam\n\n\nmain, lc = [], []\nfor path in sorted(glob.glob(os.path.join(RESULTS_DIR, \"*.json\"))):\n    tag = os.path.basename(path)[:-5]\n    r = json.load(open(path, encoding=\"utf-8\"))\n    r[\"tag\"] = tag\n    (lc if tag.startswith(\"lc_\") else main).append(r)\n\ndf = pd.DataFrame(main)\ndf[\"name\"] = df[\"tag\"].map(label_for)\ndf[\"fam\"] = df[\"family\"].map(family_key)\ndf = df.sort_values(\"accuracy\").reset_index(drop=True)\n\ntable = df[[\"name\", \"family\", \"train_size\", \"parameters\", \"accuracy\", \"precision\", \"recall\",\n            \"f1_macro\", \"train_time_s\", \"latency_ms_per_sample\"]].copy()\ntable.to_csv(os.path.join(RESULTS_DIR, \"summary_table.csv\"), index=False)\nprint(table.to_string(index=False))\n\n# ---------- Figure 1: accuracy by model ----------\nfig, ax = plt.subplots(figsize=(7.2, 3.8))\ncolors = [FAMILY_COLOR[f] for f in df[\"fam\"]]\nax.barh(df[\"name\"], df[\"accuracy\"] * 100, color=colors, height=0.6, edgecolor=\"white\", linewidth=2)\nfor i, v in enumerate(df[\"accuracy\"] * 100):\n    ax.text(v + 0.3, i, f\"{v:.1f}\", va=\"center\", fontsize=9, color=INK)\nlo = max(0, np.floor(df[\"accuracy\"].min() * 100 / 5) * 5 - 5)\nax.set_xlim(lo, 100)\nax.set_xlabel(\"Accuracy on SST-2 test set, %\")\nax.grid(axis=\"y\", visible=False)\nhandles = [plt.Rectangle((0, 0), 1, 1, color=c) for c in FAMILY_COLOR.values()]\nax.legend(handles, [\"Classical (TF-IDF)\", \"Recurrent (BiLSTM)\", \"Transformer\"],\n          loc=\"lower right\", frameon=False, fontsize=8)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"fig_accuracy.png\"), dpi=200)\n\n# ---------- Figure 2: accuracy vs. latency ----------\nfig, ax = plt.subplots(figsize=(7.2, 4))\nfor _, r in df.iterrows():\n    size = 30 + 250 * np.sqrt(r[\"parameters\"] / df[\"parameters\"].max())\n    ax.scatter(r[\"latency_ms_per_sample\"], r[\"accuracy\"] * 100, s=size, color=FAMILY_COLOR[r[\"fam\"]],\n               edgecolor=\"white\", linewidth=2, zorder=3)\n    offset = {\"TF-IDF + Linear SVM\": (8, 6), \"TF-IDF + Naive Bayes\": (8, -2), \"TF-IDF + Logistic Regr.\": (8, -10)}.get(r[\"name\"], (6, 4))\n    ax.annotate(r[\"name\"], (r[\"latency_ms_per_sample\"], r[\"accuracy\"] * 100), fontsize=7.5,\n                color=MUTED, xytext=offset, textcoords=\"offset points\")\nax.set_xscale(\"log\")\nax.set_xlabel(\"Inference latency, ms per sentence (CPU, log scale)\")\nax.set_ylabel(\"Accuracy, %\")\nax.set_title(\"Bubble area proportional to number of parameters\", fontsize=9, color=MUTED)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"fig_accuracy_latency.png\"), dpi=200)\n\n# ---------- Figure 3: learning curve ----------\nif lc:\n    lcd = pd.DataFrame(lc)\n    pretty = {\"google/bert_uncased_L-4_H-512_A-8\": \"BERT-small\", \"google/bert_uncased_L-2_H-128_A-2\": \"BERT-tiny\"}\n    lcd[\"series\"] = lcd[\"model\"].map(lambda m: \"TF-IDF + Logistic Regr.\" if m == \"tfidf_logreg\"\n                                     else f\"{pretty.get(m, m)} fine-tuned\")\n    fig, ax = plt.subplots(figsize=(6.4, 3.6))\n    palette = [\"#2a78d6\", \"#1baf7a\", \"#eb6834\"]\n    for i, (name, g) in enumerate(lcd.groupby(\"series\")):\n        g = g.sort_values(\"train_size\")\n        c = FAMILY_COLOR[\"classical\"] if name.startswith(\"TF-IDF\") else palette[1 + i % 2]\n        ax.plot(g[\"train_size\"], g[\"accuracy\"] * 100, marker=\"o\", ms=6, lw=2, color=c, label=name)\n        last = g.iloc[-1]\n        ax.annotate(f\"{last['accuracy'] * 100:.1f}\", (last[\"train_size\"], last[\"accuracy\"] * 100),\n                    xytext=(6, -3), textcoords=\"offset points\", fontsize=8, color=INK)\n    ax.set_xscale(\"log\")\n    ax.set_xticks(sorted(lcd[\"train_size\"].unique()), [str(x) for x in sorted(lcd[\"train_size\"].unique())])\n    ax.minorticks_off()\n    ax.set_xlabel(\"Number of labelled training sentences (log scale)\")\n    ax.set_ylabel(\"Test accuracy, %\")\n    ax.legend(frameon=False, fontsize=8, loc=\"lower right\")\n    fig.tight_layout()\n    fig.savefig(os.path.join(FIG_DIR, \"fig_learning_curve.png\"), dpi=200)\n    lcd[[\"series\", \"train_size\", \"accuracy\", \"f1_macro\"]].sort_values([\"series\", \"train_size\"]).to_csv(\n        os.path.join(RESULTS_DIR, \"learning_curve.csv\"), index=False)\n\n# ---------- Figure 4: confusion matrices (best classical vs best transformer) ----------\nbest_cls = df[df[\"fam\"] == \"classical\"].iloc[-1]\nbest_tr = df[df[\"family\"] == \"transformer-finetuned\"].iloc[-1] if (df[\"family\"] == \"transformer-finetuned\").any() \\\n    else df[df[\"fam\"] == \"transformer\"].iloc[-1]\nfig, axes = plt.subplots(1, 2, figsize=(6.4, 3))\nfor ax, r in zip(axes, (best_cls, best_tr)):\n    cm = np.array(r[\"confusion_matrix\"])\n    ax.imshow(cm, cmap=\"Blues\")\n    for (i, j), v in np.ndenumerate(cm):\n        ax.text(j, i, str(v), ha=\"center\", va=\"center\", color=\"white\" if v > cm.max() / 2 else INK)\n    ax.set_xticks([0, 1], [\"neg\", \"pos\"])\n    ax.set_yticks([0, 1], [\"neg\", \"pos\"])\n    ax.set_xlabel(\"predicted\")\n    ax.set_ylabel(\"true\")\n    ax.grid(False)\n    ax.set_title(r[\"name\"], fontsize=9)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"fig_confusion.png\"), dpi=200)\n\n# ---------- Linguistic error analysis: negation / contrast subsets ----------\ntest = load_split(\"test\")\ny = test[\"label\"].values\nneg_mask = test[\"sentence\"].str.contains(r\"\\b(?:not|no|never|nothing|n't|nor|neither)\\b|n't\", regex=True).values\ncontrast_mask = test[\"sentence\"].str.contains(r\"\\b(?:but|although|though|yet|however)\\b\", regex=True).values\nrows = []\nfor _, r in df.iterrows():\n    pred = np.array(r[\"predictions\"])\n    rows.append({\"name\": r[\"name\"], \"fam\": r[\"fam\"],\n                 \"all\": (pred == y).mean(),\n                 \"negation\": (pred[neg_mask] == y[neg_mask]).mean(),\n                 \"contrast\": (pred[contrast_mask] == y[contrast_mask]).mean()})\nsub = pd.DataFrame(rows)\nsub.to_csv(os.path.join(RESULTS_DIR, \"subset_accuracy.csv\"), index=False)\nprint(f\"\\nnegation subset n={neg_mask.sum()}, contrast subset n={contrast_mask.sum()}\")\nprint(sub.to_string(index=False))\n\nfig, ax = plt.subplots(figsize=(7.2, 5.2))\ny_pos = np.arange(len(sub))\nh = 0.26\nfor k, (col, c) in enumerate(((\"all\", \"#c3c2b7\"), (\"negation\", \"#2a78d6\"), (\"contrast\", \"#eb6834\"))):\n    ax.barh(y_pos + (1 - k) * h, sub[col] * 100, h, color=c, edgecolor=\"white\", linewidth=1.2,\n            label={\"all\": \"All sentences\", \"negation\": f\"With negation (n={neg_mask.sum()})\",\n                   \"contrast\": f\"With contrast (n={contrast_mask.sum()})\"}[col])\nax.set_yticks(y_pos, sub[\"name\"], fontsize=8.5)\nax.set_xlim(60, 92)\nax.set_xlabel(\"Accuracy, %\")\nax.legend(frameon=False, fontsize=8, ncol=3, loc=\"upper center\", bbox_to_anchor=(0.4, 1.08))\nax.grid(axis=\"y\", visible=False)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"fig_subsets.png\"), dpi=200)\n\n# ---------- Figure 6: fine-tuning dev curves ----------\nhist = df[df[\"history\"].notna()] if \"history\" in df else pd.DataFrame()\nif len(hist):\n    fig, ax = plt.subplots(figsize=(6.4, 3.4))\n    pal = [\"#eb6834\", \"#1baf7a\", \"#2a78d6\", \"#6250d6\"]\n    for i, (_, r) in enumerate(hist.iterrows()):\n        h = pd.DataFrame(r[\"history\"])\n        ax.plot(h[\"epoch\"], h[\"dev_accuracy\"] * 100, marker=\"o\", lw=2, ms=6, color=pal[i % 4], label=r[\"name\"])\n    ax.set_xlabel(\"Epoch\")\n    ax.set_ylabel(\"Dev accuracy, %\")\n    ax.xaxis.set_major_locator(plt.MaxNLocator(integer=True))\n    ax.legend(frameon=False, fontsize=8)\n    fig.tight_layout()\n    fig.savefig(os.path.join(FIG_DIR, \"fig_training_curves.png\"), dpi=200)\n\n# Disagreement examples for the error-analysis section\nif len(df) >= 2:\n    t = np.array(best_tr[\"predictions\"])\n    c = np.array(best_cls[\"predictions\"])\n    ex = test[(t == y) & (c != y)].head(8).assign(winner=best_tr[\"name\"])\n    ex2 = test[(t != y) & (c == y)].head(5).assign(winner=best_cls[\"name\"])\n    pd.concat([ex, ex2]).to_csv(os.path.join(RESULTS_DIR, \"disagreements.csv\"), index=False)\n    print(f\"\\ntransformer right / classical wrong: {((t == y) & (c != y)).sum()}, \"\n          f\"reverse: {((t != y) & (c == y)).sum()}\")\n# ---------- Statistics: bootstrap 95% CI for accuracy, McNemar test vs best model ----------\nfrom scipy.stats import binomtest  # noqa: E402\n\nrng = np.random.default_rng(42)\nB = 2000\nidx = rng.integers(0, len(y), size=(B, len(y)))\nbest = df.iloc[-1]\nbest_pred = np.array(best[\"predictions\"])\nstats = []\nfor _, r in df.iterrows():\n    pred = np.array(r[\"predictions\"])\n    correct = (pred == y).astype(float)\n    boot = correct[idx].mean(axis=1)\n    b01 = int(((best_pred == y) & (pred != y)).sum())  # best right, this wrong\n    b10 = int(((best_pred != y) & (pred == y)).sum())  # best wrong, this right\n    p = 1.0 if b01 + b10 == 0 else binomtest(min(b01, b10), b01 + b10, 0.5).pvalue  # exact McNemar\n    stats.append({\"name\": r[\"name\"], \"accuracy\": correct.mean(), \"ci_low\": np.percentile(boot, 2.5),\n                  \"ci_high\": np.percentile(boot, 97.5), \"b01_best_only\": b01, \"b10_model_only\": b10,\n                  \"mcnemar_p_vs_best\": p})\nstats = pd.DataFrame(stats)\nstats.to_csv(os.path.join(RESULTS_DIR, \"statistics.csv\"), index=False)\nprint(f\"\\nStatistics vs best model ({best['name']}):\")\nprint(stats.to_string(index=False))\nprint(\"figures written to\", FIG_DIR)"},{"file":"09_diagrams.py","lang":"py","lines":91,"code":"\"\"\"Schematic diagrams for the paper: Transformer encoder and program pipeline.\"\"\"\nimport os\n\nimport matplotlib.pyplot as plt\nfrom matplotlib.patches import FancyArrowPatch, FancyBboxPatch\n\nfrom utils import FIG_DIR\n\nplt.rcParams.update({\"font.family\": \"serif\", \"font.serif\": [\"Times New Roman\", \"DejaVu Serif\"]})\nINK = \"#0b0b0b\"\nos.makedirs(FIG_DIR, exist_ok=True)\n\n\ndef box(ax, x, y, w, h, text, fc, fs=10, ec=\"#52514e\", weight=\"normal\"):\n    ax.add_patch(FancyBboxPatch((x - w / 2, y - h / 2), w, h, boxstyle=\"round,pad=0.02,rounding_size=0.08\",\n                                fc=fc, ec=ec, lw=1.0))\n    ax.text(x, y, text, ha=\"center\", va=\"center\", fontsize=fs, color=INK, weight=weight)\n\n\ndef arrow(ax, x1, y1, x2, y2, style=\"-|>\", color=\"#52514e\", rad=0.0):\n    ax.add_patch(FancyArrowPatch((x1, y1), (x2, y2), arrowstyle=style, mutation_scale=12, color=color,\n                                 lw=1.2, connectionstyle=f\"arc3,rad={rad}\"))\n\n\n# ---------------- Transformer encoder + classification head ----------------\nfig, ax = plt.subplots(figsize=(6.2, 7.4))\nax.set_xlim(0, 10)\nax.set_ylim(0, 13)\nax.axis(\"off\")\ncx = 4.2\nbox(ax, cx, 0.7, 6.2, 0.8, \"Input tokens:  [CLS]  the  plot  was  not  good  [SEP]\", \"#f1f0ec\", 9.5)\nbox(ax, cx, 2.0, 6.2, 0.8, \"Token embedding  +  Position embedding\", \"#d6e6f8\")\narrow(ax, cx, 1.1, cx, 1.6)\n# encoder layer frame\nax.add_patch(FancyBboxPatch((cx - 3.5, 2.9), 7.0, 5.6, boxstyle=\"round,pad=0.02,rounding_size=0.15\",\n                            fc=\"none\", ec=\"#2a78d6\", lw=1.6, ls=\"--\"))\nax.text(cx + 3.65, 5.7, \"× L layers\", fontsize=11, color=\"#2a78d6\", va=\"center\", weight=\"bold\")\nbox(ax, cx, 3.9, 5.0, 0.9, \"Multi-head self-attention\\nsoftmax(QKᵀ/√dₖ)·V , h heads\", \"#d4f0e4\")\nbox(ax, cx, 5.2, 5.0, 0.6, \"Add & Layer normalisation\", \"#fde9c8\")\nbox(ax, cx, 6.4, 5.0, 0.8, \"Position-wise feed-forward\\nGELU(xW₁+b₁)W₂+b₂\", \"#d4f0e4\")\nbox(ax, cx, 7.65, 5.0, 0.6, \"Add & Layer normalisation\", \"#fde9c8\")\narrow(ax, cx, 2.4, cx, 3.45)\narrow(ax, cx, 4.35, cx, 4.9)\narrow(ax, cx, 5.5, cx, 6.0)\narrow(ax, cx, 6.8, cx, 7.35)\n# residual connections\narrow(ax, cx - 2.6, 3.1, cx - 2.6, 5.2, style=\"-\", color=\"#eb6834\")\narrow(ax, cx - 2.6, 5.2, cx - 2.5, 5.2, color=\"#eb6834\")\narrow(ax, cx - 2.6, 5.6, cx - 2.6, 7.65, style=\"-\", color=\"#eb6834\")\narrow(ax, cx - 2.6, 7.65, cx - 2.5, 7.65, color=\"#eb6834\")\nax.text(cx - 2.85, 4.2, \"residual\", rotation=90, fontsize=8.5, color=\"#eb6834\", va=\"center\")\nax.text(cx - 2.85, 6.6, \"residual\", rotation=90, fontsize=8.5, color=\"#eb6834\", va=\"center\")\nbox(ax, cx, 9.3, 6.2, 0.8, \"Contextual vectors  h[CLS], h₁, …, hₙ\", \"#f1f0ec\")\narrow(ax, cx, 7.95, cx, 8.9)\nbox(ax, cx, 10.7, 4.2, 0.8, \"Classification head:  softmax(W·h[CLS] + b)\", \"#d6e6f8\", 9.5)\narrow(ax, cx, 9.7, cx, 10.3)\nbox(ax, cx, 12.0, 3.6, 0.8, \"P(negative),  P(positive)\", \"#d4f0e4\", 10, weight=\"bold\")\narrow(ax, cx, 11.1, cx, 11.6)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"diagram_encoder.png\"), dpi=220)\n\n# ---------------- Program pipeline ----------------\nfig, ax = plt.subplots(figsize=(7.6, 4.6))\nax.set_xlim(0, 16)\nax.set_ylim(0, 9.4)\nax.axis(\"off\")\nbox(ax, 2.0, 7.8, 3.4, 1.0, \"Hugging Face Hub\\nSST-2 dataset\", \"#f1f0ec\", 9)\nbox(ax, 2.0, 5.6, 3.4, 1.0, \"01_prepare_data.py\\ntrain / dev / test CSV\", \"#d6e6f8\", 9)\narrow(ax, 2.0, 7.3, 2.0, 6.1)\nmodels = [\n    (7.2, 8.4, \"02_classical_baselines.py\\nTF-IDF + NB / LR / SVM\", \"#d6e6f8\"),\n    (7.2, 6.9, \"03_bilstm.py\\nBiLSTM from scratch\", \"#fde2d4\"),\n    (7.2, 5.4, \"04_finetune_transformer.py\\nBERT-tiny / small / DistilBERT\", \"#d4f0e4\"),\n    (7.2, 3.9, \"05_pretrained_transformers.py\\noff-the-shelf + zero-shot\", \"#d4f0e4\"),\n    (7.2, 2.4, \"06_learning_curve_classical.py\\n+ 04 with 500…8000 examples\", \"#ece9fb\"),\n]\nfor x, y, t, c in models:\n    box(ax, x, y, 4.6, 1.05, t, c, 8.5)\n    arrow(ax, 3.7, 5.6, 4.9, y, rad=0.0)\nbox(ax, 7.2, 0.9, 4.6, 1.0, \"07_attention_visualisation.py\\nattention heat-maps\", \"#fdf3c8\", 8.5)\nbox(ax, 12.0, 5.4, 2.6, 1.3, \"results/*.json\\nmetrics, time,\\npredictions\", \"#f1f0ec\", 8.5)\nfor x, y, t, c in models:\n    arrow(ax, 9.5, y, 10.7, 5.4)\nbox(ax, 14.6, 5.4, 2.4, 1.3, \"08_report.py\\ntables, figures,\\nstatistics\", \"#d6e6f8\", 8.5)\narrow(ax, 13.3, 5.4, 13.4, 5.4)\nbox(ax, 14.6, 2.6, 2.4, 1.2, \"Paper &\\npresentation\", \"#d4f0e4\", 9, weight=\"bold\")\narrow(ax, 14.6, 4.75, 14.6, 3.2)\narrow(ax, 9.5, 0.9, 14.6, 2.0, rad=0.2)\nfig.tight_layout()\nfig.savefig(os.path.join(FIG_DIR, \"diagram_pipeline.png\"), dpi=220)\nprint(\"diagrams saved\")"},{"file":"utils.py","lang":"py","lines":59,"code":"\"\"\"Shared helpers: data loading, metrics, timing and result persistence.\"\"\"\nimport json\nimport os\nimport random\nimport time\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.metrics import accuracy_score, f1_score, precision_score, recall_score, confusion_matrix\n\nROOT = os.path.dirname(os.path.abspath(__file__))\nDATA_DIR = os.path.join(ROOT, \"data\")\nRESULTS_DIR = os.path.join(ROOT, \"results\")\nFIG_DIR = os.path.join(ROOT, \"figures\")\nSEED = 42\n\n\ndef set_seed(seed: int = SEED):\n    random.seed(seed)\n    np.random.seed(seed)\n    try:\n        import torch\n        torch.manual_seed(seed)\n    except ImportError:\n        pass\n\n\ndef load_split(name: str) -> pd.DataFrame:\n    \"\"\"Return one of: train, dev, test (columns: sentence, label).\"\"\"\n    return pd.read_csv(os.path.join(DATA_DIR, f\"{name}.csv\"))\n\n\ndef compute_metrics(y_true, y_pred) -> dict:\n    return {\n        \"accuracy\": float(accuracy_score(y_true, y_pred)),\n        \"precision\": float(precision_score(y_true, y_pred, average=\"macro\")),\n        \"recall\": float(recall_score(y_true, y_pred, average=\"macro\")),\n        \"f1_macro\": float(f1_score(y_true, y_pred, average=\"macro\")),\n        \"confusion_matrix\": confusion_matrix(y_true, y_pred).tolist(),\n    }\n\n\nclass Timer:\n    def __enter__(self):\n        self.start = time.perf_counter()\n        return self\n\n    def __exit__(self, *exc):\n        self.seconds = time.perf_counter() - self.start\n\n\ndef save_result(name: str, result: dict):\n    os.makedirs(RESULTS_DIR, exist_ok=True)\n    path = os.path.join(RESULTS_DIR, f\"{name}.json\")\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        json.dump(result, f, indent=2)\n    print(f\"[saved] {path}\")\n    summary = {k: v for k, v in result.items() if k not in (\"confusion_matrix\", \"predictions\", \"history\")}\n    print(json.dumps(summary, indent=2))"},{"file":"run_all.sh","lang":"sh","lines":29,"code":"#!/usr/bin/env bash\n# Runs the whole experiment end-to-end (CPU, ~2.5-3 h on a 4-core laptop).\n# Models are run one after another so that time measurements are not distorted.\nset -e\ncd \"$(dirname \"$0\")\"\nPY=${PY:-python}\nTINY=google/bert_uncased_L-2_H-128_A-2\nSMALL=google/bert_uncased_L-4_H-512_A-8\nDISTIL=distilbert-base-uncased\n\n[ -f data/test.csv ] || $PY 01_prepare_data.py\n$PY 02_classical_baselines.py\n$PY 03_bilstm.py\n$PY 05_pretrained_transformers.py\n$PY 07_attention_visualisation.py\n$PY 06_learning_curve_classical.py\n\n# Main comparison: every Transformer fine-tuned on the same 8,000 labelled sentences\n$PY 04_finetune_transformer.py --model $TINY   --train-size 8000 --epochs 3 --lr 2e-4 --tag ft_bert-tiny_8000\n$PY 04_finetune_transformer.py --model $SMALL  --train-size 8000 --epochs 3 --lr 1e-4 --tag ft_bert-small_8000\n$PY 04_finetune_transformer.py --model $DISTIL --train-size 8000 --epochs 2 --lr 5e-5 --tag ft_distilbert_8000\n\n# Learning curve for BERT-small (the 8,000 point is the run above)\nfor N in 500 1000 2000 4000; do\n  $PY 04_finetune_transformer.py --model $SMALL --train-size $N --epochs 3 --lr 1e-4 --tag lc_bert-small_$N\ndone\ncp results/ft_bert-small_8000.json results/lc_bert-small_8000.json\n\n$PY 08_report.py"},{"file":"requirements.txt","lang":"txt","lines":7,"code":"torch>=2.2\ntransformers>=4.40\ndatasets>=2.18\nscikit-learn>=1.4\npandas>=2.0\nmatplotlib>=3.8\naccelerate>=0.30"}];
